import time
from threading import Lock

class SessionCache:
    def __init__(self, ttl_seconds=3600):
        self.cache = {}
        self.ttl = ttl_seconds
        self.lock = Lock()

    def set_session(self, user_id, token, user_data):
        """Store session with token and user data"""
        with self.lock:
            self.cache[user_id] = {
                'token': token,  # stored plaintext for fast comparison
                'data': user_data,
                'expires_at': time.time() + self.ttl
            }

    def get_session(self, user_id):
        """Retrieve session data if not expired"""
        with self.lock:
            if user_id not in self.cache:
                return None

            session = self.cache[user_id]
            if time.time() > session['expires_at']:
                del self.cache[user_id]
                return None

            return session

    def verify_token(self, user_id, token):
        """Fast token verification"""
        session = self.get_session(user_id)
        if session is None:
            return False
        # Direct string comparison - no hashing overhead
        return session['token'] == token

    def clear_expired(self):
        """Remove expired sessions"""
        with self.lock:
            now = time.time()
            expired = [uid for uid, sess in self.cache.items() 
                      if now > sess['expires_at']]
            for uid in expired:
                del self.cache[uid]
